solution.solution.cpp:
#include <algorithm>
#include <deque>
#include <map>
#include <optional>
#include <set>
#include <string>
#include <utility>
#include <vector>

enum class Outcome { Acquired, AcquiredAbandoned, Waiting, Deadlock, OrderViolation };
using Grant = std::pair<int, Outcome>;

class LockManager
{
public:
    void setRank(const std::string& lock, int rank) { ranks[lock] = rank; }

    Outcome acquire(int process, const std::string& lock)
    {
        Lock& l{ locks[lock] };
        if (l.owner && *l.owner == process) { ++l.count; return Outcome::Acquired; }
        const auto r{ ranks.find(lock) };
        if (r != ranks.end())
            for (const auto& [name, other] : locks)
                if (name != lock && other.owner && *other.owner == process && ranks.count(name) && ranks.at(name) >= r->second)
                    return Outcome::OrderViolation;
        if (!l.owner)
        {
            l.owner = process;
            l.count = 1;
            if (l.abandoned) { l.abandoned = false; return Outcome::AcquiredAbandoned; }
            return Outcome::Acquired;
        }
        // Would waiting close a cycle? Follow owner -> the lock it waits for -> that lock's owner ...
        std::set<int> seen;
        std::optional<int> at{ l.owner };
        while (at && !seen.count(*at))
        {
            if (*at == process) return Outcome::Deadlock;
            seen.insert(*at);
            const auto w{ waitingFor.find(*at) };
            if (w == waitingFor.end()) break;
            at = locks[w->second].owner;
        }
        l.queue.push_back(process);
        waitingFor[process] = lock;
        return Outcome::Waiting;
    }

    std::vector<Grant> release(int process, const std::string& lock)
    {
        const auto it{ locks.find(lock) };
        if (it == locks.end() || !it->second.owner || *it->second.owner != process) return {};
        if (--it->second.count > 0) return {};
        it->second.owner.reset();
        return handOn(lock, Outcome::Acquired);
    }

    std::vector<Grant> processDied(int process)
    {
        if (const auto w{ waitingFor.find(process) }; w != waitingFor.end())
        {
            auto& q{ locks[w->second].queue };
            q.erase(std::remove(q.begin(), q.end(), process), q.end());
            waitingFor.erase(w);
        }
        std::vector<Grant> grants;
        for (auto& [name, l] : locks)
        {
            if (!l.owner || *l.owner != process) continue;
            l.owner.reset();
            l.count = 0;
            l.abandoned = true;
            for (const Grant& g : handOn(name, Outcome::AcquiredAbandoned)) grants.push_back(g);
        }
        return grants;
    }

    std::optional<int> owner(const std::string& lock) const
    {
        const auto it{ locks.find(lock) };
        return it == locks.end() ? std::nullopt : it->second.owner;
    }

    std::vector<std::string> held(int process) const
    {
        std::vector<std::string> out;
        for (const auto& [name, l] : locks) if (l.owner && *l.owner == process) out.push_back(name);
        return out;
    }

    std::vector<int> waiters(const std::string& lock) const
    {
        const auto it{ locks.find(lock) };
        if (it == locks.end()) return {};
        return { it->second.queue.begin(), it->second.queue.end() };
    }

private:
    struct Lock { std::optional<int> owner; int count{ 0 }; bool abandoned{ false }; std::deque<int> queue; };
    std::map<std::string, Lock> locks;
    std::map<std::string, int> ranks;
    std::map<int, std::string> waitingFor;

    std::vector<Grant> handOn(const std::string& name, Outcome how)
    {
        Lock& l{ locks[name] };
        if (l.queue.empty()) return {};
        const int next{ l.queue.front() };
        l.queue.pop_front();
        waitingFor.erase(next);
        l.owner = next;
        l.count = 1;
        l.abandoned = false;
        return { { next, how } };
    }
};

unitTests:
using Grants = std::vector<Grant>;
TEST("recursive ownership and a fair queue") {
    LockManager m;
    CHECK(m.acquire(1, "log") == Outcome::Acquired);
    CHECK(m.acquire(1, "log") == Outcome::Acquired);
    CHECK(m.acquire(2, "log") == Outcome::Waiting);
    CHECK(m.acquire(3, "log") == Outcome::Waiting);
    CHECK_EQ(m.waiters("log"), (std::vector<int>{ 2, 3 }));
    CHECK(m.release(1, "log").empty());
    CHECK(m.release(1, "log") == (Grants{ { 2, Outcome::Acquired } }));
    CHECK_EQ(m.owner("log").value_or(0), 2);
    CHECK(m.release(9, "log").empty());
    CHECK(m.release(2, "log") == (Grants{ { 3, Outcome::Acquired } }));
}
TEST("lock order") {
    LockManager m;
    m.setRank("settings", 1);
    m.setRank("cache", 2);
    CHECK(m.acquire(1, "cache") == Outcome::Acquired);
    CHECK(m.acquire(1, "settings") == Outcome::OrderViolation);
    CHECK(m.acquire(1, "unranked") == Outcome::Acquired);
    CHECK_EQ(m.held(1), (std::vector<std::string>{ "cache", "unranked" }));
    CHECK(m.acquire(2, "settings") == Outcome::Acquired);
    CHECK(m.acquire(2, "cache") == Outcome::Waiting);
}
TEST("deadlocks are refused") {
    LockManager m;
    m.acquire(1, "a");
    m.acquire(2, "b");
    CHECK(m.acquire(1, "b") == Outcome::Waiting);
    CHECK(m.acquire(2, "a") == Outcome::Deadlock);
    CHECK_EQ(m.waiters("a"), std::vector<int>{});
    m.acquire(3, "c");
    CHECK(m.acquire(3, "a") == Outcome::Waiting);
    CHECK(m.acquire(2, "c") == Outcome::Deadlock);
}
TEST("a dead owner's locks are abandoned") {
    LockManager m;
    m.acquire(1, "data");
    m.acquire(1, "data");
    m.acquire(1, "index");
    m.acquire(2, "index");
    const Grants g{ m.processDied(1) };
    CHECK(g == (Grants{ { 2, Outcome::AcquiredAbandoned } }));
    CHECK(!m.owner("data").has_value());
    CHECK(m.acquire(3, "data") == Outcome::AcquiredAbandoned);
    m.release(3, "data");
    CHECK(m.acquire(4, "data") == Outcome::Acquired);
}
TEST("a dead waiter leaves the queue") {
    LockManager m;
    m.acquire(1, "x");
    m.acquire(2, "x");
    m.acquire(3, "x");
    CHECK(m.processDied(2).empty());
    CHECK_EQ(m.waiters("x"), (std::vector<int>{ 3 }));
    CHECK(m.release(1, "x") == (Grants{ { 3, Outcome::Acquired } }));
}

